  split.Dock=DockStyle.Fill;split.Orientation=Orientation.Horizontal;split.Size=new Size(900,550);split.SplitterDistance=260;split.Panel1MinSize=90;split.Panel2MinSize=160;layout.Controls.Add(split,0,3);
  grid.Dock=DockStyle.Fill;grid.ReadOnly=true;grid.AllowUserToAddRows=false;grid.AllowUserToDeleteRows=false;grid.RowHeadersVisible=false;grid.SelectionMode=DataGridViewSelectionMode.FullRowSelect;grid.MultiSelect=false;grid.BackgroundColor=SystemColors.Window;grid.BorderStyle=BorderStyle.FixedSingle;grid.AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.Fill;grid.AutoGenerateColumns=false;
  AddColumn("Count","Issues",45,45);AddColumn("Category","Type",110,90);AddColumn("Source","Location",180,100);AddColumn("Text","Player-facing text",400,120);split.Panel1.Controls.Add(grid);grid.SelectionChanged+=(s,e)=>{if(!binding)Details();};grid.CellDoubleClick+=(s,e)=>{if(e.RowIndex>=0)Navigate();};grid.ColumnHeaderMouseClick+=(s,e)=>{string key=grid.Columns[e.ColumnIndex].Name;if(sort==key)ascending=!ascending;else{sort=key;ascending=true;}Bind(Selected==null?null:Selected.Identity,0);};
