 void Button(Control parent,Button button,string text,Action action,string help){button.Text=text;button.AutoSize=true;button.Height=28;button.Margin=new Padding(0,2,6,2);button.Click+=(s,e)=>action();tips.SetToolTip(button,help);parent.Controls.Add(button);}
 void AddColumn(string key,string header,int weight,int min){grid.Columns.Add(new DataGridViewTextBoxColumn{Name=key,HeaderText=header,FillWeight=weight,MinimumWidth=min,SortMode=DataGridViewColumnSortMode.Programmatic});}
 public void RefreshProject(){if(bridge.Game==null||string.IsNullOrEmpty(bridge.Root)){status.Text="Open an AGS game first.";return;}if(session==null||!string.Equals(session.Root,Path.GetFullPath(bridge.Root),StringComparison.OrdinalIgnoreCase))ResetProject();}
 public void ResetProject(){generation++;busy=false;lines.Clear();cache.Clear();session=null;Run(()=>{if(bridge.Game!=null&&!string.IsNullOrEmpty(bridge.Root)){session=new ReviewSession(bridge);checker.Language=System.Windows.Markup.XmlLanguage.GetLanguage(session.State.Language);title.Text="AGS Spellchecker  /  "+new DirectoryInfo(session.Root).Name;}});Bind(null,0);status.Text="Scan the open game to begin. Offline English spelling, grammar and punctuation checks.";}
 string CacheKey(LineItem x){return (x.Entry.Prose?"p:":"l:")+x.Text;}
 List<Issue> Check(string text,bool prose){return Proof.Check(checker,text,session.ProofState,prose);}
 async void Scan(bool reuse){if(busy)return;RefreshProject();if(session==null)return;int token=++generation;busy=true;UpdateActions();status.Text="Reading player-facing text from the open AGS project…";string selected=Selected==null?null:Selected.Identity;int index=grid.CurrentRow==null?0:grid.CurrentRow.Index;
  try{await Task.Delay(1);if(token!=generation)return;bridge.CheckCapabilities();var found=bridge.Extract();if(!reuse)cache.Clear();int count=0;foreach(var line in found){if(token!=generation)return;line.Ignored=session.State.Ignored.Contains(line.Entry.Key);if(!line.Ignored){List<Issue> result;string key=CacheKey(line);if(!cache.TryGetValue(key,out result)){result=Check(line.Text,line.Entry.Prose);cache[key]=result;}line.Issues=result;line.Checked=true;}count++;if(count%16==0){status.Text="Checking "+count+" of "+found.Count+" lines…";await Task.Delay(1);}}if(token!=generation)return;lines=found;busy=false;Bind(selected,index);status.Text=Summary();if(bridge.Warnings.Count>0)status.Text+="  "+bridge.Warnings.Count+" sources skipped — see History / settings.";}
  catch(Exception ex){if(token==generation){busy=false;status.Text="Scan could not finish: "+ex.Message;}}finally{if(token==generation){busy=false;UpdateActions();}}
 }
 string Summary(){return lines.Count(x=>!session.State.Ignored.Contains(x.Entry.Key)&&x.Count>0)+" lines with potential issues · "+lines.Count+" player-facing lines scanned. Apply saves the AGS project and a backup.";}
 void Bind(string identity,int index){if(IsDisposed)return;binding=true;try{grid.Rows.Clear();if(session!=null){var query=lines.Where(x=>x.Checked&&x.Count>0&&!session.State.Ignored.Contains(x.Entry.Key));if(category.SelectedIndex>0)query=query.Where(x=>x.Category==(string)category.SelectedItem);if(search.TextLength>0)query=query.Where(x=>(x.Text+" "+x.Source).IndexOf(search.Text,StringComparison.CurrentCultureIgnoreCase)>=0);Func<LineItem,IComparable> key=x=>sort=="Count"?(IComparable)x.Count:sort=="Category"?x.Category:sort=="Text"?x.Text:x.Source;var sorted=ascending?query.OrderBy(key):query.OrderByDescending(key);foreach(var line in sorted){int n=grid.Rows.Add(line.Count,line.Category,line.Source,line.Entry.Preview);grid.Rows[n].Tag=line;}if(grid.Rows.Count>0){int n=identity==null?-1:grid.Rows.Cast<DataGridViewRow>().ToList().FindIndex(r=>((LineItem)r.Tag).Identity==identity);if(n<0)n=Math.Min(index,grid.Rows.Count-1);grid.CurrentCell=grid.Rows[Math.Max(0,n)].Cells[0];}}foreach(DataGridViewColumn c in grid.Columns)c.HeaderCell.SortGlyphDirection=c.Name==sort?(ascending?SortOrder.Ascending:SortOrder.Descending):SortOrder.None;}finally{binding=false;}Details();}
 void Details(){binding=true;try{var line=Selected;edit.Text=line==null?"":line.Text;location.Text=line==null?"No potential issues in this view":line.Source+" — edit below, then Apply & next";context.Text="";if(line!=null){if(line.Target.Script){string[] raw=line.Target.Snapshot.Replace("\r\n","\n").Split('\n');int n=Project.Line(line.Target.Snapshot,line.Entry.Start)-1;context.Text=string.Join(Environment.NewLine,raw.Select((s,i)=>new{i,s}).Where(x=>x.i>=n-2&&x.i<=n+2).Select(x=>(x.i==n?"> ":"  ")+(x.i+1)+"  "+x.s));}else context.Text=line.Target.Caption+Environment.NewLine+"Current value: "+line.Text;}}finally{binding=false;}CheckDraft();}
 void CheckDraft(){issues.Items.Clear();draftIssues.Clear();if(session!=null&&Selected!=null){try{draftIssues=Check(edit.Text,Selected.Entry.Prose);foreach(var issue in draftIssues)issues.Items.Add(issue);if(issues.Items.Count>0)issues.SelectedIndex=0;}catch(Exception ex){status.Text="Checking failed: "+ex.Message;}}SuggestionList();UpdateActions();}
 void SuggestionList(){suggestions.Items.Clear();var issue=issues.SelectedItem as Issue;if(issue!=null){foreach(string s in issue.Suggestions)suggestions.Items.Add(s);if(suggestions.Items.Count>0)suggestions.SelectedIndex=0;}UpdateActions();}
 void UseSuggestion(){var issue=issues.SelectedItem as Issue;var suggestion=suggestions.SelectedItem as string;if(issue==null||suggestion==null)return;int pos=issue.Start;edit.Text=edit.Text.Remove(pos,issue.Length).Insert(pos,suggestion);edit.Focus();edit.Select(pos,suggestion.Length);}
 void Apply(){var line=Selected;if(line==null)return;int index=grid.CurrentRow.Index;session.Apply(line,edit.Text);cache.Clear();lines.Remove(line);Bind(null,index);Scan(true);}
 void AddWord(){var issue=issues.SelectedItem as Issue;if(issue==null||issue.Kind!="Spelling")return;int index=grid.CurrentRow.Index;string selected=Selected.Identity;session.AddWord(edit.Text.Substring(issue.Start,issue.Length));cache.Clear();foreach(var line in lines.Where(x=>x.Checked&&!x.Ignored))line.Issues=Check(line.Text,line.Entry.Prose);Bind(null,index);if(Selected!=null&&Selected.Identity==selected&&grid.Rows.Count>1)grid.CurrentCell=grid.Rows[(index+1)%grid.Rows.Count].Cells[0];status.Text=Summary();}
 void Navigate(){Run(()=>{var line=Selected;if(line==null)return;line.Target.Navigate(line.Target.Script?Project.Line(line.Target.Snapshot,line.Entry.Start):1);});}
 void UpdateActions(){bool selected=Selected!=null&&session!=null&&!busy;scan.Enabled=session!=null&&!busy;cancel.Enabled=busy;go.Enabled=selected;apply.Enabled=selected&&edit.Text!=Selected.Text;ignore.Enabled=selected;word.Enabled=selected&&issues.SelectedItem is Issue&&((Issue)issues.SelectedItem).Kind=="Spelling";use.Enabled=selected&&suggestions.SelectedItem!=null;undo.Enabled=session!=null&&!busy&&session.State.History.Any(x=>!x.Undone);edit.ReadOnly=!selected;grid.Enabled=!busy;}
 void Run(Action action){try{action();}catch(Exception ex){status.Text=ex.Message;MessageBox.Show(this,ex.Message,"AGS Spellchecker",MessageBoxButtons.OK,MessageBoxIcon.Information);}UpdateActions();}
 void Help(){MessageBox.Show(this,"1. Scan game checks player-facing text in the open project. Only lines with potential issues are shown. Filter by type or click a column heading to sort.\n\n2. Select a line. Use suggestion edits the draft; you can also type your own correction. Go to source opens its script line or property in AGS.\n\n3. Apply & next backs up the original, saves through AGS, then selects the next issue. This also saves other pending AGS edits. Ignore and Add word are remembered for this game.\n\nUndo last edit restores a correction if the same document has not changed again. History shows the backup folder.\n\nAll checking is offline. English grammar rules catch common mistakes, not every grammatical error. Custom text-display wrappers and text assembled from variables may need manual review. Hover over buttons for help.","Using AGS Spellchecker",MessageBoxButtons.OK,MessageBoxIcon.Information);}
 void Settings(){if(session==null)return;using(var form=new Form{Text="AGS Spellchecker — history and settings",Size=new Size(800,560),StartPosition=FormStartPosition.CenterParent,MinimizeBox=false,MaximizeBox=true}){var layout=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=1,RowCount=4,Padding=new Padding(12)};layout.RowStyles.Add(new RowStyle(SizeType.Absolute,35));layout.RowStyles.Add(new RowStyle(SizeType.Percent,100));layout.RowStyles.Add(new RowStyle(SizeType.Absolute,45));layout.RowStyles.Add(new RowStyle(SizeType.Absolute,40));form.Controls.Add(layout);var label=new Label{Dock=DockStyle.Fill,Text="Backups: "+session.Store,AutoEllipsis=true};tips.SetToolTip(label,session.Store);layout.Controls.Add(label,0,0);var history=new TextBox{Multiline=true,ReadOnly=true,ScrollBars=ScrollBars.Both,WordWrap=false,Dock=DockStyle.Fill};history.Text=string.Join(Environment.NewLine,session.State.History.AsEnumerable().Reverse().Select(x=>x.When+"  "+(x.Undone?"UNDONE":x.Saved?"SAVED":"SAVE INCOMPLETE")+"  "+x.Caption+Environment.NewLine+"  "+x.BeforeText+" → "+x.AfterText))+Environment.NewLine+Environment.NewLine+"Scan warnings:"+Environment.NewLine+string.Join(Environment.NewLine,bridge.Warnings);layout.Controls.Add(history,0,1);var settings=new FlowLayoutPanel{Dock=DockStyle.Fill};layout.Controls.Add(settings,0,2);settings.Controls.Add(new Label{Text="Dictionary:",AutoSize=true,Margin=new Padding(0,8,6,0)});var language=new ComboBox();language.DropDownStyle=ComboBoxStyle.DropDownList;language.Items.AddRange(new object[]{"en-US","en-GB","en-CA","en-AU"});language.SelectedItem=checker.Language.IetfLanguageTag;settings.Controls.Add(language);Button(settings,new Button(),"Reset ignored lines ("+session.State.Ignored.Count+")",()=>Run(()=>{session.State.Ignored.Clear();session.SaveState();form.Close();Scan(false);}),"Show previously ignored lines again for this game.");Button(settings,new Button(),"Edit dictionary",()=>Dictionary(form),"Add or remove game-specific words, one word per line.");var footer=new FlowLayoutPanel{Dock=DockStyle.Fill,FlowDirection=FlowDirection.RightToLeft};layout.Controls.Add(footer,0,3);Button(footer,new Button(),"Done",()=>{string lang=(string)language.SelectedItem;if(lang!=checker.Language.IetfLanguageTag){checker.Language=System.Windows.Markup.XmlLanguage.GetLanguage(lang);session.State.Language=lang;session.SaveState();cache.Clear();form.Close();Scan(false);}else form.Close();},"Return to review.");form.ShowDialog(this);}}
 void Dictionary(Form parent){using(var form=new Form{Text="Game dictionary — one word per line",Size=new Size(400,450),StartPosition=FormStartPosition.CenterParent}){var text=new TextBox{Dock=DockStyle.Fill,Multiline=true,ScrollBars=ScrollBars.Vertical,Text=string.Join(Environment.NewLine,session.State.Words.OrderBy(x=>x))};var save=new Button{Text="Save dictionary",Dock=DockStyle.Bottom,Height=35};form.Controls.Add(text);form.Controls.Add(save);save.Click+=(s,e)=>Run(()=>{session.State.Words=text.Text.Split(new[]{'\r','\n'},StringSplitOptions.RemoveEmptyEntries).Select(x=>x.Trim().ToLowerInvariant()).Where(x=>x.Length>0).Distinct().ToList();session.SaveState();form.Close();parent.Close();cache.Clear();Scan(false);});form.ShowDialog(parent);}}
}
